 ['desk','panel','joint','table','van'].forEach(function(kind){if((kind==='table'||kind==='van')&&!K.by[kind])return;var q=HS_BAY[kind];list.push({kind:kind,x:q[0],y:q[1],k:K.by[kind]||0})});
